CREATE OR REPLACE VIEW public.finance_unit_report WITH(security_invoker=true) AS WITH rent AS(SELECT cu.unit_id,sum(cu.annual_rent_excl_vat) AS contract_rent FROM public.contract_units cu JOIN public.contracts c ON c.id=cu.contract_id WHERE c.status='active' GROUP BY cu.unit_id),money AS(SELECT cu.unit_id,sum(a.amount_excl_vat*cu.annual_rent_excl_vat/nullif(c.annual_rent_excl_vat,0)) AS collected_excl_vat,sum(a.vat_amount*cu.annual_rent_excl_vat/nullif(c.annual_rent_excl_vat,0)) AS collected_vat,count(DISTINCT r.id) AS receipts_count FROM public.receipt_allocations a JOIN public.receipt_cash_read r ON r.id=a.receipt_id JOIN public.installments i ON i.id=a.installment_id JOIN public.contracts c ON c.id=i.contract_id JOIN public.contract_units cu ON cu.contract_id=c.id WHERE r.status='verified' AND r.reverses_id IS NULL GROUP BY cu.unit_id),due AS(SELECT cu.unit_id,sum(greatest(0,i.amount_incl_vat-coalesce(p.paid,0))*cu.annual_rent_excl_vat/nullif(c.annual_rent_excl_vat,0)) AS remaining_incl_vat FROM public.installments i JOIN public.contracts c ON c.id=i.contract_id JOIN public.contract_units cu ON cu.contract_id=c.id LEFT JOIN LATERAL(SELECT sum(a.amount_incl_vat) AS paid FROM public.receipt_allocations a JOIN public.receipt_cash_read r ON r.id=a.receipt_id WHERE a.installment_id=i.id AND r.status='verified' AND r.reverses_id IS NULL) p ON true WHERE c.status='active' AND i.status<>'waived' GROUP BY cu.unit_id) SELECT u.id,u.building_number,u.unit_number,u.unit_type,u.leasing_status,rent.contract_rent,round(coalesce(money.collected_excl_vat,0),2) AS collected_excl_vat,round(coalesce(money.collected_vat,0),2) AS collected_vat,coalesce(money.receipts_count,0) AS receipts_count,round(due.remaining_incl_vat,2) AS remaining_incl_vat FROM public.units u LEFT JOIN rent ON rent.unit_id=u.id LEFT JOIN money ON money.unit_id=u.id LEFT JOIN due ON due.unit_id=u.id WHERE NOT u.is_test AND public.finance_can_read();
GRANT SELECT ON public.finance_unit_report TO authenticated,service_role;
SELECT count(*) AS eligible_units FROM public.finance_unit_report;